import json, pathlib, subprocess, tempfile, textwrap; repo = pathlib.Path.cwd(); fz = repo / 'target/debug/fz'

def write_project(name, source):
    root = pathlib.Path(tempfile.mkdtemp(prefix=f'fozzylang-{name}-'))
    (root / 'src').mkdir(parents=True, exist_ok=True)
    (root / 'fozzy.toml').write_text(textwrap.dedent(f'''\
        [package]
        name="{name}"
        version="0.1.0"

        [[target.bin]]
        name="{name}"
        path="src/main.fzy"
    '''))
    (root / 'src/main.fzy').write_text(textwrap.dedent(source))
    return root

def verify(name, source, expect_rc):
    root = write_project(name, source)
    proc = subprocess.run([str(fz), 'verify', str(root), '--json'], cwd=str(repo), capture_output=True, text=True)
    payload = json.loads(proc.stdout.strip())
    assert proc.returncode == expect_rc, (name, proc.returncode, payload, proc.stderr)
    return payload

def messages(payload):
    return [item['message'] for item in payload['items']]

def find_message(payload, needle):
    return next(item for item in payload['items'] if needle in item['message'])

tuple_partial = verify('tuple_partial', '''
    fn main() -> i32 {
        let pair: (*mut u8, *mut u8) = (alloc(32), alloc(32))
        let (left, _) = pair
        close(left)
        return 0
    }
''', 1)
tuple_diag = find_message(tuple_partial, 'performs partial move from owned aggregate')
assert 'borrow fields instead of extracting only one owned subvalue' in (tuple_diag.get('help') or ''), tuple_diag

nested_field_partial = verify('nested_field_partial', '''
    struct Inner { ptr: *mut u8 }
    struct Outer { inner: Inner, tag: i32 }
    fn main() -> i32 {
        let outer: Outer = Outer { inner: Inner { ptr: alloc(32) }, tag: 7 }
        let ptr = outer.inner.ptr
        close(ptr)
        return 0
    }
''', 1)
assert any('performs partial move from owned aggregate' in message for message in messages(nested_field_partial)), nested_field_partial

struct_pattern_partial = verify('struct_pattern_partial', '''
    struct Pair { left: *mut u8, right: *mut u8 }
    fn main() -> i32 {
        let pair: Pair = Pair { left: alloc(32), right: alloc(32) }
        let Pair { left, right: _ } = pair
        close(left)
        return 0
    }
''', 1)
assert any('performs partial move from owned aggregate' in message for message in messages(struct_pattern_partial)), struct_pattern_partial

enum_partial = verify('enum_partial', '''
    enum Pairish { Both(*mut u8, *mut u8), Empty }
    fn main() -> i32 {
        let pair = Pairish::Both(alloc(32), alloc(32))
        match pair {
            Pairish::Both(left, _) => close(left),
            _ => return 0,
        }
        return 0
    }
''', 1)
assert any('performs partial move from owned aggregate' in message for message in messages(enum_partial)), enum_partial

assignment_partial = verify('assignment_partial', '''
    struct Inner { ptr: *mut u8 }
    struct Outer { inner: Inner, tag: i32 }
    fn main() -> i32 {
        let mut ptr = alloc(8)
        let outer: Outer = Outer { inner: Inner { ptr: alloc(32) }, tag: 7 }
        ptr = outer.inner.ptr
        close(ptr)
        return 0
    }
''', 1)
assignment_diag = find_message(assignment_partial, 'performs partial move assignment from owned aggregate')
assert 'borrow fields instead of extracting only one owned subvalue' in (assignment_diag.get('help') or ''), assignment_diag

full_tuple_pass = verify('full_tuple_pass', '''
    fn main() -> i32 {
        let pair: (*mut u8, *mut u8) = (alloc(32), alloc(32))
        let (left, right) = pair
        close(left)
        close(right)
        return 0
    }
''', 0)
assert full_tuple_pass['errors'] == 0, full_tuple_pass
assert not any('partial move' in message for message in messages(full_tuple_pass)), full_tuple_pass

full_struct_pass = verify('full_struct_pass', '''
    struct Pair { left: *mut u8, right: *mut u8 }
    fn main() -> i32 {
        let pair: Pair = Pair { left: alloc(32), right: alloc(32) }
        let Pair { left, right } = pair
        close(left)
        close(right)
        return 0
    }
''', 0)
assert full_struct_pass['errors'] == 0, full_struct_pass
assert not any('partial move' in message for message in messages(full_struct_pass)), full_struct_pass

print('compiler-memory-partial-moves-ok')

